"""Mutalia-e-Quran XII PDF49: p.46 — verses 4:153 (begun on p.45)–158. Run: python class12_quran_page049.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p49():
    b = Builder()
    V(b, 4, 153, 'آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) سے اہلِ کتاب مطالبہ کرتے ہیں کہ آپ اُن پر آسمان سے ایک کتاب اتار لائیں پس وہ تو موسیٰ (علیہ السلام) سے اس سے زیادہ بڑا مطالبہ کر چکے ہیں تو ان لوگوں نے (موسیٰ علیہ السلام سے) کہا کہ ہمیں اللہ دکھا دو علانیہ طور پر تو اُن کے ظلم کی وجہ سے انھیں کڑک نے آ پکڑا پھر انھوں نے اس کے بعد بھی کہ ان کے پاس واضح دلائل آ چکے تھے بچھڑے کو (معبود) بنایا تو ہم نے اس (سنگین جرم) کو معاف کر دیا اور ہم نے موسیٰ (علیہ السلام) کو واضح غلبہ عطا فرمایا۔',
      'اهل کتاب له تاسو (صلی الله علیه وعلی آله واصحابه وسلم) غوښتنه کوي چې پر هغوی له اسمانه یو کتاب راکوز کړئ؛ نو هغوی خو له موسی (علیه السلام) له دې هم لویه غوښتنه کړې وه: هغو خلکو (موسی علیه السلام ته) وویل: «موږ ته الله په ښکاره وښیه»، نو د هغوی د ظلم له امله تندر ونیول؛ بیا هغوی سره له دې چې ښکاره دلیلونه ورته راغلي وو، سخی (معبود) ونیو؛ نو موږ له دې (لوی جرم) تېر شو، او موږ موسی (علیه السلام) ته ښکاره غلبه ورکړه.')
    V(b, 4, 154, 'اور ہم نے اُن سے عہد لینے کے لیے اُن پر طور (پہاڑ) بلند کیا اور ہم نے اُن سے کہا کہ (شہر کے) دروازے سے سروں کو جھکاتے ہوئے داخل ہونا اور ہم نے اُن سے کہا تھا کہ ہفتہ کے دن کے بارے میں حد سے نہ بڑھنا اور ہم نے ان سے پختہ عہد لیا۔',
      'او موږ د هغوی څخه د ژمنې اخیستو لپاره پر هغوی طور (غر) پورته کړ، او موږ ورته وویل چې د (ښار) له دروازې سرونه ټیټ ننوځئ، او موږ ورته ویلي وو چې د شنبې د ورځې په اړه له حده مه اوړئ، او موږ ترې ټینګه ژمنه واخیسته.')
    V(b, 4, 155, 'تو (ان پر لعنت کی گئی) اُن کے اپنے عہد کو توڑنے پر اور آیاتِ الٰہی سے انکار پر اور انبیاء کو ان کے ناحق قتل (شہید) کر دینے پر اور اُن کی اس بات پر کہ ہمارے دل غلاف میں (بند) ہیں (ایسا نہیں ہے) بلکہ اللہ نے ان کے کفر کی وجہ سے اُن پر مہر لگا دی پس چند لوگوں کے سوا وہ ایمان نہیں لائیں گے۔',
      'نو (پر هغوی لعنت وشو) د خپلې ژمنې د ماتولو، د الهي آیتونو د انکار، د انبیاوو د ناحقه وژلو (شهیدولو)، او د دې خبرې له امله چې «زموږ زړونه په پوښ کې (تړلي) دي» — (داسې نه ده) بلکې الله د هغوی د کفر له امله پرې مهر لګولی؛ نو له څو کسانو پرته به ایمان رانه وړي.')
    V(b, 4, 156, 'اور (ان پر لعنت کی گئی) اُن کے کفر اور اُن کے مریم (علیہا السلام) پر بہت بڑے بہتان کی بات کہنے کی وجہ سے۔',
      'او (پر هغوی لعنت وشو) د هغوی د کفر او پر مریم (علیها السلام) د ډېر لوی بهتان ویلو له امله.')
    V(b, 4, 157, 'اور (ان پر لعنت کی گئی) اُن کے اس قول کی وجہ سے کہ بے شک ہم نے مسیح عیسیٰ ابن مریم (علیہ السلام) (یعنی) اللہ کے رسول کو قتل کیا جب کہ انھوں نے قتل نہیں کیا ان کو اور نہ انھیں سولی چڑھایا مگر (ہوا یہ کہ) ان کے لیے (کسی کو عیسیٰ علیہ السلام کا) مشابہ بنا دیا گیا اور بے شک جن لوگوں نے اس بارے میں اختلاف کیا یقیناً وہ اس معاملے میں شک میں مبتلا ہیں انھیں اس کا کچھ علم نہیں سوائے گمان کی پیروی کرنے کے اور انھوں نے یقیناً ان کو قتل نہیں کیا۔',
      'او (پر هغوی لعنت وشو) د دې ویلو له امله چې «بې‌شکه موږ مسیح عیسی ابن مریم (علیه السلام)، (یعنې) د الله رسول ووژه» — حال دا چې هغوی نه دی وژلی او نه یې پر دار ځړولی، بلکې (داسې وشول چې) د هغوی لپاره (یو کس د عیسی علیه السلام) ورته کړای شو؛ او بې‌شکه هغه کسان چې په دې اړه یې اختلاف وکړ، یقیناً په دې چاره کې په شک کې دي؛ هغوی ته له ګومان له پیروۍ پرته پرې هېڅ علم نشته؛ او یقیناً یې نه دی وژلی.')
    V(b, 4, 158, 'بلکہ اللہ نے انھیں اپنی طرف اٹھا لیا اور اللہ بڑا غالب بڑی حکمت والا ہے۔',
      'بلکې الله هغه خپل لوري ته پورته کړ، او الله ډېر غالب، ډېر حکمتناک دی.')
    BOOK.save(49, [(5, rec(b, 5, 49, 49))], issues=[{'id': 'mq12-pdf049', 'unit': 5, 'printedPage': 46,
               'description': 'Verse 4:153 (begun on p.45) recorded here.'}])


if __name__ == '__main__':
    p49()
